/**
 * lorebook.ts — the Lorebook Agent's host integration.
 *
 *   bun tests/lorebook.ts
 *
 * `router.js` is 5,799 lines and reaches the host two ways: through
 * `getContext()` (already shimmed) and through 13 raw `fetch('/api/worldinfo/*')`
 * calls — rewritten to `stFetch` by the port script — that bypass it entirely, because upstream needed to defeat
 * SillyTavern's stale `worldInfoCache`.
 *
 * Those are served in-process by `compat/worldinfo-rest.ts` rather than
 * rewritten, since `src/engine/` is regenerated by the port script. This checks
 * the seam: the endpoints answer in the shapes the agent expects, reads and
 * writes reach `spindle.world_books`, and the pipeline that fires the agent is
 * wired to the engine's own scheduler rather than an invented trigger.
 */

import { emitHostEvent, installFakeSpindle } from './fake-spindle'

const state = installFakeSpindle()
state.messages.set('chat-1', [
  {
    id: 'm1', chat_id: 'chat-1', index_in_chat: 0, is_user: true, role: 'user',
    name: 'You', content: 'I ask the innkeeper about the ruins.', send_date: 0,
    swipe_id: 0, swipes: ['I ask the innkeeper about the ruins.'], swipe_dates: [0],
    extra: {}, parent_message_id: null, branch_id: null, created_at: 0,
  },
])

let failures = 0
const check = (label: string, ok: boolean, detail = ''): void => {
  if (!ok) failures++
  console.log(`  ${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`)
}

await import('../src/backend')
// What the engine's fetch calls are rewritten to; see compat/worldinfo-rest.ts.
const { stFetch } = await import('../src/compat/st-core')
await emitHostEvent(state, 'CHAT_SWITCHED', { chatId: 'chat-1' })
await new Promise(resolve => setTimeout(resolve, 400))

console.log('── world info REST shim ──')

// `list` — the agent reads `file_id` off each row.
await spindle.world_books.create({ name: 'Campaign Lore', description: '' }, 'user-1')
const listResponse = await stFetch('/api/worldinfo/list', { method: 'POST' })
check('list responds ok', listResponse.ok, String(listResponse.status))
const listed = await listResponse.json() as Array<{ file_id?: string }>
check('list returns file_id rows',
  Array.isArray(listed) && listed.some(row => row.file_id === 'Campaign Lore'),
  JSON.stringify(listed))

// `get` — a missing book must be a 404, not an empty document. The agent
// treats a completed response as authoritative, so `{entries:{}}` would read as
// "this book exists and is empty" and it would stop creating it.
const missing = await stFetch('/api/worldinfo/get', {
  method: 'POST', body: JSON.stringify({ name: 'Does Not Exist' }),
})
check('missing book is a 404, not an empty document', missing.status === 404,
  String(missing.status))

// `edit` — write two entries through the raw endpoint.
const edit = await stFetch('/api/worldinfo/edit', {
  method: 'POST',
  body: JSON.stringify({
    name: 'Campaign Lore',
    data: {
      entries: {
        0: {
          uid: 0, key: ['ruins', 'Old Keep'], keysecondary: [],
          comment: 'The Old Keep', content: 'A ruined keep north of the village.',
          constant: false, selective: true, disable: false,
          order: 100, position: 0, probability: 100, useProbability: false,
          depth: 4, excludeRecursion: false,
        },
        1: {
          uid: 1, key: ['innkeeper'], keysecondary: [],
          comment: 'Bram the innkeeper', content: 'Runs the Sleeping Hart.',
          constant: false, selective: true, disable: false,
          order: 100, position: 0, probability: 100, useProbability: false,
          depth: 4, excludeRecursion: false,
        },
      },
    },
  }),
})
check('edit responds ok', edit.ok, String(edit.status))
check('entries reached spindle.world_books', state.entries.size === 2,
  `${state.entries.size} entr(ies)`)

const stored = [...state.entries.values()]
check('translated ST order to Lumiverse order_value',
  stored.every(entry => entry.order_value === 100),
  JSON.stringify(stored.map(e => e.order_value)))
check('translated ST disable to Lumiverse disabled',
  stored.every(entry => entry.disabled === false),
  JSON.stringify(stored.map(e => e.disabled)))

// `get` — round-trip back into ST document shape.
const getResponse = await stFetch('/api/worldinfo/get', {
  method: 'POST', body: JSON.stringify({ name: 'Campaign Lore' }),
})
check('get responds ok', getResponse.ok, String(getResponse.status))
const doc = await getResponse.json() as { entries?: Record<string, Record<string, unknown>> }
const entries = Object.values(doc.entries ?? {})
check('round-tripped both entries', entries.length === 2, String(entries.length))
check('kept keys and content',
  entries.some(e => Array.isArray(e.key) && (e.key as string[]).includes('ruins')
    && String(e.content).includes('ruined keep')),
  JSON.stringify(entries[0]?.key))
check('restored ST field names',
  entries.every(e => 'order' in e && 'disable' in e && 'uid' in e),
  Object.keys(entries[0] ?? {}).join(', '))

console.log('\n── non-world-info endpoints still fail loudly ──')
// `getRequestHeaders()` used to throw. That caught unported call sites by
// accident — and blocked ported ones by accident too, which cost the Map
// Architect its save. The guard lives here alone now, so it has to hold on its
// own for every SillyTavern route the engine still reaches for.
const { getRequestHeaders } = await import('../src/compat/st-core')
check('headers no longer throw', typeof getRequestHeaders() === 'object',
  JSON.stringify(getRequestHeaders()))

for (const route of ['/api/characters/all', '/api/settings/get', '/api/images/upload']) {
  try {
    await stFetch(route, { method: 'POST', headers: getRequestHeaders() })
    check(`${route} rejects`, false, 'it resolved')
  } catch (error) {
    check(`${route} rejects by name`,
      (error as Error).message.includes(route),
      (error as Error).message.slice(0, 60))
  }
}

console.log('\n── pipeline wiring ──')
const hooks = globalThis as Record<string, unknown>
check('_rpgRunStateModelPass installed', typeof hooks._rpgRunStateModelPass === 'function')
check('_rpgStateModelRunning installed', typeof hooks._rpgStateModelRunning === 'function')
check('_rpgRenderRouterUI installed', typeof hooks._rpgRenderRouterUI === 'function')

const bridge = await import('../src/engine/src/app/runtime-bridge.js') as {
  isRouterRunning: () => boolean
}
check('isRouterRunning resolves through the action table',
  bridge.isRouterRunning() === false, String(bridge.isRouterRunning()))

const narrative = await import('../src/engine/narrative-hooks.js') as {
  onGenerationEnded?: () => Promise<void>
  onGenerationStarted?: (type?: string) => void
}
check('engine exposes the post-generation pipeline',
  typeof narrative.onGenerationEnded === 'function'
    && typeof narrative.onGenerationStarted === 'function')

// The agent is off by default, so a turn must complete without running it.
await emitHostEvent(state, 'GENERATION_ENDED', { chatId: 'chat-1' })
await new Promise(resolve => setTimeout(resolve, 600))
check('a turn completes with the agent disabled', true)

const errors = state.logs.filter(entry => entry.level === 'error')
console.log('\n── errors ──')
if (!errors.length) console.log('  (none)')
for (const entry of errors) console.log(`  ${entry.message}`)
check('no errors during the pipeline', errors.length === 0, errors[0]?.message ?? '')

console.log(`\n${failures === 0 ? 'lorebook test passed' : `${failures} check(s) failed`}`)
process.exit(failures === 0 ? 0 : 1)
